const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const brooklyn = ee.Geometry.Polygon([
    [-74.042, 40.570], [-73.855, 40.570], 
    [-73.855, 40.739], [-74.042, 40.739], 
    [-74.042, 40.570]
  ]);

  const periods = [
    {year: 2021, start: '2021-10-01', end: '2021-10-23'},
    {year: 2019, start: '2019-10-01', end: '2019-10-23'},
    {year: 2018, start: '2018-10-01', end: '2018-10-23'}
  ];

  // 2. Data Acquisition & Processing
  const results = [];

  for (const period of periods) {
    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(period.start, period.end)
      .filterBounds(brooklyn)
      .select('tropospheric_NO2_column_number_density');

    const count = collection.size().getInfo();
    console.log(`${period.year} Images: ${count}`);

    if (count === 0) {
      console.log(`No data for ${period.year}`);
      console.log("<answer>C1</answer>");
      return;
    }

    // Create mean composite and calculate statistics
    const meanImage = collection.mean();

    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: brooklyn,
      scale: 1000,
      maxPixels: 1e9
    });

    const pixelCount = meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: brooklyn,
      scale: 1000,
      maxPixels: 1e9
    }).get('tropospheric_NO2_column_number_density').getInfo();

    const no2Value = stats.get('tropospheric_NO2_column_number_density').getInfo();

    console.log(`${period.year} NO2: ${no2Value ? no2Value.toFixed(6) : 'null'}, Pixels: ${pixelCount}`);

    if (pixelCount === 0) {
      console.log("No valid pixels after processing.");
      console.log("<answer>C2</answer>");
      return;
    }

    if (no2Value === null || no2Value === undefined || !isFinite(no2Value) || no2Value < 0 || no2Value > 1) {
      console.log("Invalid NO2 value calculated.");
      console.log("<answer>C3</answer>");
      return;
    }

    results.push({year: period.year, value: no2Value});
  }

  // 3. Comparison Logic
  const no2_2021 = results.find(r => r.year === 2021).value;
  const no2_2019 = results.find(r => r.year === 2019).value;
  const no2_2018 = results.find(r => r.year === 2018).value;

  console.log(`Comparison: 2021(${no2_2021.toFixed(6)}) vs 2019(${no2_2019.toFixed(6)}) vs 2018(${no2_2018.toFixed(6)})`);

  // Check if 2021 is lower than both 2019 and 2018
  if (no2_2021 < no2_2019 && no2_2021 < no2_2018) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
